    /// {IERC7579Hook-postCheck} are tolerated and the uninstallation proceeds. For any other module type the hook
    /// checks behave as usual and their reverts propagate.
    function _uninstallModule(
        uint256 moduleTypeId,
        address module,
        bytes memory deInitData
    ) internal virtual override {
        address hook_ = hook();

        if (moduleTypeId == MODULE_TYPE_HOOK) {
            // Uninstalling the hook module itself: tolerate preCheck/postCheck reverts (including the hook having no
            // code). postCheck is only attempted if preCheck succeeded.
            bytes memory hookData;
            bool prechecked;
            if (hook_ != address(0)) {
                // slither-disable-next-line reentrancy-no-eth
                try IERC7579Hook(hook_).preCheck(msg.sender, msg.value, msg.data) returns (bytes memory data) {
                    hookData = data;
                    prechecked = true;
                } catch {}
            }

